"""Request-time cost selection for policies generated by the low-cost template.

The immutable application provenance identifies this template. Ordinary route_to
policies keep their concrete target. No mutable policy draft is read at runtime.
"""

from __future__ import annotations

import json
import sqlite3
from decimal import Decimal
from typing import Any
from uuid import uuid4

from metahub_shared.runtime.config import AppConfig
from metahub_shared.runtime.errors import ApiError
from metahub_shared.runtime.policy_snapshot import PolicySnapshotItem
from metahub_shared.runtime.provider_adapter_spec import (
    CUSTOMER_MANAGED,
    LOCAL_COMPATIBLE,
    MODEL_VENDOR_CLOUD,
    ProviderAdapterSpecError,
    provider_adapter_spec,
)
from metahub_shared.runtime.routing_policy import (
    MAX_ROUTING_CANDIDATES,
    TokenEstimate,
    estimate_routing_candidate_cost,
    evaluate_routing_candidates_phase_one,
)

from .models import (
    GatewayRoutePlan,
    _connect,
    _load_policy_candidate_row,
    _load_routing_prices,
    _normalize_environment,
    _resolve_environment_id,
    _route_from_row,
    _routing_candidate_input,
    _routing_request_token_estimate,
    _to_db_time,
    _utcnow,
)


def resolve_low_cost_template_plan(
    config: AppConfig,
    *,
    tenant_id: str,
    policy: PolicySnapshotItem | None,
    project_id: str | None,
    snapshot_version: int | None,
    requested_model: str,
    environment: str,
    environment_id: str | None,
    request_id: str,
    trace_id: str,
    virtual_key_id: str,
    request_kind: str,
    payload: dict[str, Any],
    trusted_token_estimate: TokenEstimate | None = None,
) -> GatewayRoutePlan | None:
    """Return a fresh cost plan only for an unchanged, tenant-bound template policy.

    Old published template instances also use fresh prices. A missing policy in
    the leased snapshot (including an empty rollback) cannot activate this path.
    """
    if policy is None or policy.action_type != "route_to" or not project_id:
        return None
    connection = _connect(config)
    try:
        connection.execute("BEGIN IMMEDIATE")
        try:
            application = connection.execute(
                """
                SELECT a.application_id,a.generated_policy_version,a.result_snapshot_version,
                       d.resource_id AS preview_model_id
                FROM policy_template_applications a
                JOIN policy_template_application_dependencies d
                  ON d.tenant_id=a.tenant_id AND d.application_id=a.application_id
                 AND d.resource_type='model' AND d.relation='route_target'
                WHERE a.tenant_id=? AND a.generated_policy_id=? AND a.project_id=?
                  AND a.policy_template_id='ptpl_low_cost_mode'
                """,
                (tenant_id, policy.policy_id, project_id),
            ).fetchone()
        except sqlite3.OperationalError as exc:
            # Compatibility with fixtures/deployments predating the template catalog.
            if "no such table" not in str(exc).lower():
                raise
            return None
        if (
            application is None
            or policy.policy_version != application["generated_policy_version"]
            or policy.target_model_id != application["preview_model_id"]
            or snapshot_version is None
            or snapshot_version < application["result_snapshot_version"]
        ):
            return None

        normalized_environment = _normalize_environment(environment)
        resolved_environment_id = _resolve_environment_id(
            connection,
            tenant_id,
            normalized_environment,
            environment_id,
        )
        as_of = _utcnow()
        estimate = _routing_request_token_estimate(
            request_kind,
            payload,
            trusted_token_estimate=trusted_token_estimate,
        )
        quoted: list[tuple[Decimal, str, sqlite3.Row, dict[str, object]]] = []
        model_ids = connection.execute(
            "SELECT model_id FROM models WHERE tenant_id=? AND status='active' ORDER BY model_id",
            (tenant_id,),
        ).fetchall()
        for model in model_ids:
            row = _load_policy_candidate_row(connection, tenant_id, model["model_id"])
            if row is None or row["provider_id"] is None:
                continue
            try:
                spec = provider_adapter_spec(row["provider_type"])
                capabilities = json.loads(row["capabilities"])
            except (TypeError, json.JSONDecodeError, ProviderAdapterSpecError):
                continue
            if spec.classification not in {MODEL_VENDOR_CLOUD, LOCAL_COMPATIBLE, CUSTOMER_MANAGED}:
                continue
            required = ("chat", "stream") if request_kind == "chat" else ("embeddings",)
            if not isinstance(capabilities, dict) or any(
                capabilities.get(key) is not True for key in required
            ):
                continue
            candidate = _routing_candidate_input(
                config,
                connection,
                row,
                role="default",
                priority=0,
                routing_mode="cost_first",
                as_of=as_of,
            )
            if not evaluate_routing_candidates_phase_one(
                "cost_first", (candidate,)
            ).eligible_candidates:
                continue
            price = _load_routing_prices(connection, tenant_id, (str(row["model_id"]),), as_of)[0]
            cost = estimate_routing_candidate_cost(price, estimate)
            if cost is None:
                continue
            quoted.append(
                (
                    cost[1],
                    str(row["model_id"]),
                    row,
                    {
                        "model_id": str(row["model_id"]),
                        "provider_id": str(row["provider_id"]),
                        "price_source": price.source,
                        "price_schema_version": price.price_schema_version,
                        "currency": price.currency,
                        "estimated_cost_amount": str(cost[0]),
                        "comparison_cost_cny": str(cost[1]),
                        "comparison_fx_rate": str(price.comparison_fx_rate)
                        if price.comparison_fx_rate
                        else None,
                        "comparison_fx_rate_version": price.comparison_fx_rate_version,
                    },
                )
            )
        quoted.sort(key=lambda item: (item[0], item[1]))
        routes = tuple(
            _route_from_row(
                item[2],
                requested_model=requested_model,
                environment=normalized_environment,
                environment_id=resolved_environment_id,
                model_alias_id=None,
                public_model_alias=None,
                routing_reason="policy.cost_first",
            )
            for item in quoted[:MAX_ROUTING_CANDIDATES]
        )
        selected = routes[0] if routes else None
        decision_id = str(uuid4())
        # Dynamic selection must be auditable before any upstream request is sent.
        connection.execute(
            """
            INSERT INTO routing_decisions(
              routing_decision_id,tenant_id,request_id,trace_id,virtual_key_id,model_alias_id,
              requested_model,environment,environment_id,selected_model_id,
              selected_internal_model_id,provider_id,provider_code,decision_status,
              decision_reason,candidate_summary,error_code,created_at
            ) VALUES(?,?,?,?,?,NULL,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                decision_id,
                tenant_id,
                request_id,
                trace_id,
                virtual_key_id,
                requested_model,
                normalized_environment,
                resolved_environment_id,
                selected.model_id if selected else None,
                selected.model_alias if selected else None,
                selected.provider_id if selected else None,
                selected.provider_code if selected else None,
                "selected" if selected else "failed",
                "policy.cost_first",
                json.dumps(
                    {
                        "policy_id": policy.policy_id,
                        "snapshot_version": snapshot_version,
                        "routing_mode": "cost_first",
                        "price_as_of": _to_db_time(as_of),
                        "input_tokens": estimate.input_tokens,
                        "output_tokens": estimate.output_tokens,
                        "candidate_count": len(quoted),
                        "candidates": [item[3] for item in quoted[:MAX_ROUTING_CANDIDATES]],
                    },
                    sort_keys=True,
                ),
                None if selected else "gateway.no_route_available",
                _to_db_time(as_of),
            ),
        )
        connection.commit()
        if selected is None:
            raise ApiError("gateway.no_route_available")
        return GatewayRoutePlan(
            initial_route=selected,
            initial_role="primary",
            fallback_route=routes[1] if len(routes) > 1 else None,
            fallback_routes=routes[1:],
            fallback_conditions=(
                "upstream_timeout",
                "upstream_unavailable",
                "upstream_rate_limited",
                "upstream_quota_exceeded",
                "upstream_5xx",
            ),
            routing_mode="cost_first",
            routing_decision_id=decision_id,
            token_estimate=estimate,
            routing_as_of=as_of,
        )
    except ApiError:
        connection.rollback()
        raise
    except (sqlite3.Error, ValueError, TypeError) as exc:
        connection.rollback()
        raise ApiError("gateway.routing_snapshot_unavailable") from exc
    finally:
        connection.close()
